<script setup>
import { money, timeLabel, paymentMethodLabel } from '#shared/utils/format.js'
const {isOwner}=useAuth();const {toast,error:formatError}=useFeedback()
const {data:payments,refresh,error}=await useFetch('/api/payments',{default:()=>[]})
const {data:report,refresh:refreshReport}=await useFetch('/api/reports')
const search=ref('');const status=ref('');const page=ref(1);const refundId=ref(null);const busy=ref(false);const message=ref('')
const rows=computed(()=>payments.value.filter(p=>(!status.value||p.status===status.value)&&(!search.value||`${p.orderNumber} ${p.customerName} ${p.paymentReference}`.toLowerCase().includes(search.value.toLowerCase()))))
const visible=computed(()=>rows.value.slice((page.value-1)*10,page.value*10));watch([search,status],()=>page.value=1)
const collected=computed(()=>payments.value.filter(p=>p.status==='SUCCESS').reduce((n,p)=>n+Number(p.amount),0))
const refunded=computed(()=>payments.value.filter(p=>p.status==='REFUNDED').reduce((n,p)=>n+Number(p.amount),0))
async function refund(){busy.value=true;message.value='';try{await $fetch(`/api/payments/${refundId.value}/refund`,{method:'POST'});toast('Refund dicatat; tagihan order diperbarui');refundId.value=null;await refresh();await refreshReport()}catch(e){message.value=formatError(e)}finally{busy.value=false}}
</script><template><div><LayoutPageHeader title="Payments" description="Catatan pembayaran yang jelas untuk setiap pelayanan." eyebrow="FINANCE"><UiButton to="/orders" variant="secondary">Pilih order untuk pembayaran<UiIcon name="arrow" :size="16" /></UiButton></LayoutPageHeader><div class="finance-metrics"><div class="metric-card"><span>Pembayaran diterima</span><strong class="metric-value">{{ money(collected) }}</strong><p>Akumulasi pembayaran sukses</p></div><div class="metric-card"><span>Refund</span><strong class="metric-value">{{ money(refunded) }}</strong><p>Pembayaran yang telah dikembalikan</p></div><div class="metric-card"><span>Total transaksi</span><strong class="metric-value">{{ payments.length }}</strong><p>Histori pembayaran tersimpan</p></div></div><div class="finance-metrics"><div v-for="[key,label] in [['ownerShare','Bagian owner'],['adminShare','Bagian admin'],['therapistShare','Bagian therapist']]" :key="key" class="metric-card"><span>{{ label }}</span><strong class="metric-value">{{ money(report?.summary[key]) }}</strong><p>Setelah refund · seluruh order</p></div></div><p class="form-hint mb-4">Pembagian layanan setelah diskon; transport dan pajak terpisah. <NuxtLink to="/reports/revenue" class="text-link">Lihat laporan pembagian</NuxtLink></p><section class="panel"><div class="filter-bar"><div class="search-control"><UiIcon name="search" :size="17" /><input v-model="search" placeholder="Cari transaksi atau customer…" aria-label="Cari pembayaran" /></div><select v-model="status" aria-label="Status pembayaran"><option value="">Semua status</option><option value="SUCCESS">Sukses</option><option value="REFUNDED">Refund</option></select></div><p v-if="error" class="error-message">{{ error.data?.statusMessage }}</p><div class="table-wrap"><table><thead><tr><th>Order / Customer</th><th>Tanggal pembayaran</th><th>Metode</th><th>Referensi</th><th>Jumlah</th><th>Status</th><th /></tr></thead><tbody><tr v-for="p in visible" :key="p.id"><td><NuxtLink :to="'/orders/'+p.orderId" class="table-main">{{ p.customerName }}</NuxtLink><small class="table-sub">{{ p.orderNumber }} · {{ p.locationName }}</small></td><td>{{ timeLabel(p.paidAt) }}</td><td>{{ paymentMethodLabel(p.paymentMethod) }}</td><td>{{ p.paymentReference||'—' }}</td><td class="table-price">{{ money(p.amount) }}</td><td><UiBadge :status="p.status" /></td><td><button v-if="isOwner&&p.status==='SUCCESS'" class="text-link danger-text" @click="refundId=p.id">Refund</button></td></tr></tbody></table><UiEmptyState v-if="!rows.length" title="Belum ada pembayaran" message="Catat pembayaran pada detail order yang dipilih." icon="payments" /></div><UiPagination v-model:page="page" :total="rows.length" /></section><UiModal :open="!!refundId" title="Catat refund?" @close="refundId=null"><p>Gunakan setelah dana dikembalikan kepada customer. Catatan ini memperbarui tagihan order dan mempertahankan histori transaksi.</p><p v-if="message" class="error-message">{{ message }}</p><div class="modal-actions"><UiButton variant="secondary" @click="refundId=null">Batal</UiButton><UiButton variant="danger" :loading="busy" @click="refund">Catat refund</UiButton></div></UiModal></div></template>